// <auto-generated companion /> — standard lit scene submit (mirrors SubmitStandardLitSceneFromWorld).
#nullable enable
namespace Spark.Bindings;

public static class SceneSubmit
{
    public static void StandardLit(
        GameWorld world,
        IEngineContext context,
        in Camera2D camera,
        in Vector3 lightDirectionWorld,
        in Vector3 lightColor,
        float lightIntensity,
        in Vector3 ambientColor,
        float sceneTimeSeconds,
        bool enableParticles = false,
        SparkSpriteSortMode spriteSortMode = SparkSpriteSortMode.SparkSpriteSortMode_SortOrderThenWorldY)
    {
        context.GetFramebufferSize(out int fbW, out int fbH);
        if (fbW <= 0)
        {
            fbW = 1;
        }
        if (fbH <= 0)
        {
            fbH = 1;
        }

        var viewProj = camera.ViewProjection(fbW, fbH);
        camera.BillboardBasisWorld(out var camRight, out var camUp);

        world.SubmitStandardLit(
            context,
            viewProj,
            camera.Position,
            lightDirectionWorld,
            lightColor,
            lightIntensity,
            ambientColor,
            enableParticles,
            camRight,
            camUp,
            sceneTimeSeconds,
            spriteSortMode);
    }
}
